import path from 'node:path';
import { runMigrations } from './migrate';
import * as schema from './schema';

/** Drizzle migrations folder (baseline + everything generated by drizzle-kit). */
const DRIZZLE_DIR = path.join(process.cwd(), 'drizzle');


export interface Db {
	close?(): Promise<void>;
	query(sql: string, params?: unknown[]): Promise<{ rows: any[] }>;
}

interface Opened extends Db {
	drizzle: any;
	migrateDrizzle(folder: string): Promise<void>;
}

let db: Promise<Opened> | undefined;

/**
 * Returns the singleton DB connection, lazily opening it (Postgres via
 * DATABASE_URL, or PGlite otherwise) and running pending migrations to
 * completion exactly once before the first caller sees it.
 */
function getOpened(): Promise<Opened> {
	if (!db) {
		db = open().then(async (opened) => {
			process.once('sveltekit:shutdown' as any, async () => {
				try {
					await opened.close?.();
				} catch (err) {
					console.error('error closing database', err);
				}
			});
			await runMigrations(opened);
			await opened.migrateDrizzle(DRIZZLE_DIR);
			return opened;
		});
	}
	return db;
}

export async function getDb(): Promise<Db> {
	return getOpened();
}

/** The Drizzle instance on the same connection, migrated before first use. */
export async function getDrizzle() {
	return (await getOpened()).drizzle as import('drizzle-orm/pg-core').PgDatabase<any, typeof schema>;
}

async function open(): Promise<Opened> {
	if (process.env.DATABASE_URL) {
		return openPostgres(process.env.DATABASE_URL);
	}
	return openPglite(process.env.PGLITE_DATA_DIR ?? './data/pglite');
}

async function openPostgres(connectionString: string): Promise<Opened> {
	const { Pool } = await import('pg');
	const pool = new Pool({ connectionString });
	const { drizzle } = await import('drizzle-orm/node-postgres');
	const d = drizzle(pool, { schema });
	return {
		drizzle: d,
		async migrateDrizzle(migrationsFolder) {
			const { migrate } = await import('drizzle-orm/node-postgres/migrator');
			await migrate(d, { migrationsFolder });
		},
		async query(sql, params) {
			const result = await pool.query(sql, params);
			return { rows: result.rows };
		},
		close: () => pool.end()
	};
}

async function openPglite(dataDir: string): Promise<Opened> {
	const { PGlite } = await import('@electric-sql/pglite');
	if (dataDir !== 'memory://') {
		const { mkdir } = await import('node:fs/promises');
		await mkdir(dataDir, { recursive: true });
	}
	const pglite = dataDir === 'memory://' ? new PGlite() : new PGlite(dataDir);
	const { drizzle } = await import('drizzle-orm/pglite');
	const d = drizzle(pglite, { schema });
	return {
		...wrapPglite(pglite),
		close: () => pglite.close(),
		drizzle: d,
		async migrateDrizzle(migrationsFolder) {
			const { migrate } = await import('drizzle-orm/pglite/migrator');
			await migrate(d, { migrationsFolder });
		}
	};
}

/**
 * Adapts a PGlite instance to Db. Without params the SQL goes through exec()
 * (simple protocol), so multi-statement text works as it does with `pg`.
 */
export function wrapPglite(pglite: {
	query(sql: string, params?: any[]): Promise<{ rows: any[] }>;
	exec(sql: string): Promise<{ rows: any[] }[]>;
}): Db {
	return {
		async query(sql, params) {
			if (!params || params.length === 0) {
				const results = await pglite.exec(sql);
				return { rows: (results[results.length - 1]?.rows ?? []) as any[] };
			}
			const result = await pglite.query(sql, params as any[]);
			return { rows: result.rows as any[] };
		}
	};
}
